insert into public.policy_clauses (section, title, body, adoption_count) select 'waste', 'Zero landfill and the waste hierarchy', 'The school aims to send nothing to landfill. It tackles waste in order: refuse what is not needed, reduce what is, reuse and repurpose what remains, and only then recycle. Procurement and the canteen share responsibility for cutting waste at the source. Source: Green School Bali, Environmental Policy Pledges (https://sites.google.com/greenschool.org/environmental-hub/pledges), adapted.', 0 where not exists (select 1 from public.policy_clauses where title = 'Zero landfill and the waste hierarchy');
insert into public.policy_clauses (section, title, body, adoption_count) select 'water', 'Replenishing the water we use', 'The school aims to return as much water to the ground as it takes, through projects led by students. It monitors use, harvests rainwater, cuts waste and reuses water wherever it is safe to do so. Source: Green School Bali, Environmental Policy Pledges (https://sites.google.com/greenschool.org/environmental-hub/pledges), adapted.', 0 where not exists (select 1 from public.policy_clauses where title = 'Replenishing the water we use');
insert into public.policy_clauses (section, title, body, adoption_count) select 'food', 'Food from seed to compost', 'The canteen serves nutritious, seasonal, local and ethically sourced food, organic where possible, with little single-use packaging. Students learn the whole food cycle by growing food and composting what is left over. Source: Green School Bali, Environmental Policy Pledges (https://sites.google.com/greenschool.org/environmental-hub/pledges), adapted.', 0 where not exists (select 1 from public.policy_clauses where title = 'Food from seed to compost');
insert into public.policy_clauses (section, title, body, adoption_count) select 'transport', 'Low-carbon transport', 'The school defaults to the lowest-carbon way of travelling, plans trips to reduce their number, and supports cycling, shared transport and cleaner fuels for school vehicles. Source: Green School Bali, Environmental Policy Pledges (https://sites.google.com/greenschool.org/environmental-hub/pledges), adapted.', 0 where not exists (select 1 from public.policy_clauses where title = 'Low-carbon transport');
insert into public.policy_clauses (section, title, body, adoption_count) select 'biodiversity', 'Campus species census', 'Students survey and record the plants and animals on campus to build a living census. The school uses the results to guide building work and to add to wild spaces rather than shrink them. Source: Green School Bali, Environmental Policy Pledges (https://sites.google.com/greenschool.org/environmental-hub/pledges), adapted.', 0 where not exists (select 1 from public.policy_clauses where title = 'Campus species census');
insert into public.policy_clauses (section, title, body, adoption_count) select 'building', 'Green building and play spaces', 'New building work protects existing green space, uses local and sustainable materials, and reuses existing structures where possible. Nature-based play areas and food gardens are part of the design, not an afterthought. Source: Green School Bali, Environmental Policy Pledges (https://sites.google.com/greenschool.org/environmental-hub/pledges), adapted.', 0 where not exists (select 1 from public.policy_clauses where title = 'Green building and play spaces');
